-- Read-only structural/security release gate for migration 030.
with checks(check_type, object_name, passed, explanation) as (
  select 'columns', v.column_name, exists (select 1 from information_schema.columns c where c.table_schema='public' and c.table_name='sps_staged_orders' and c.column_name=v.column_name), 'Required SPS provenance column exists.' from (values ('document_type'),('sps_id'),('fulfillment_document_id'),('business_po_number'),('source_filename'),('source_received_at'),('source_delivered_at'),('payload_hash'),('source_change_date'),('source_change_indicator'),('source_document_key'),('parent_staged_order_id')) v(column_name)
  union all select 'nullable_columns', 'legacy provenance remains nullable', (select count(*)=12 from information_schema.columns c where c.table_schema='public' and c.table_name='sps_staged_orders' and c.column_name in ('document_type','sps_id','fulfillment_document_id','business_po_number','source_filename','source_received_at','source_delivered_at','payload_hash','source_change_date','source_change_indicator','source_document_key','parent_staged_order_id') and c.is_nullable='YES'), 'Legacy/sandbox evidence is intentionally not rewritten.'
  union all select 'constraints','sps_staged_orders_document_type_check', exists(select 1 from pg_constraint where conname='sps_staged_orders_document_type_check' and pg_get_constraintdef(oid) like '%850%' and pg_get_constraintdef(oid) like '%860%'), 'Only 850/860 values are accepted when populated.'
  union all select 'indexes','replacement durable source identity', exists(select 1 from pg_indexes where schemaname='public' and indexname='sps_staged_orders_source_document_key_unique'), 'Non-null identity is unique by organization and source.'
  union all select 'indexes','legacy partner/PO uniqueness removed', not exists(select 1 from pg_indexes where schemaname='public' and indexname in ('sps_staged_orders_partner_po_unique','sps_staged_orders_global_po_unique')), 'Business PO no longer collapses 850/860 documents.'
  union all select 'indexes','business PO lookup index', exists(select 1 from pg_indexes where schemaname='public' and indexname='sps_staged_orders_business_po_idx'), 'Review lookup index exists.'
  union all select 'indexes','parent lookup index', exists(select 1 from pg_indexes where schemaname='public' and indexname='sps_staged_orders_parent_idx'), 'Parent review lookup index exists.'
  union all select 'triggers','six SPS write-role gates', (select count(*)=6 from pg_trigger where not tgisinternal and tgname in ('enforce_lucid_sps_customer_mapping_write_role','enforce_lucid_sps_ship_to_mapping_write_role','enforce_lucid_sps_item_mapping_write_role','enforce_lucid_sps_staged_order_write_role','enforce_lucid_sps_staged_line_write_role','enforce_lucid_sps_exception_write_role')), 'All SPS mutation surfaces have a role gate.'
  union all select 'triggers','promoted source immutability', (select count(*)=3 from pg_trigger where not tgisinternal and tgname in ('protect_lucid_promoted_sps_staged_order','protect_lucid_promoted_sps_staged_line','protect_lucid_promoted_sps_exception')), 'Promoted headers, lines, and exceptions cannot be rewritten.'
  union all select 'triggers','parent same-org scope', exists(select 1 from pg_trigger where not tgisinternal and tgname='validate_lucid_sps_parent_scope'), 'Parent references are validated at the database boundary.'
  union all select 'triggers','reconciliation audit triggers', (select count(*)=4 from pg_trigger where not tgisinternal and tgname in ('audit_lucid_sps_customer_mapping_change','audit_lucid_sps_ship_to_mapping_change','audit_lucid_sps_item_mapping_change','audit_lucid_sps_exception_resolution')), 'Material reconciliation actions are audit-backed.'
  union all select 'functions','required function objects', (select count(*)=5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('assert_lucid_sps_write_role','validate_lucid_sps_parent_scope','protect_lucid_promoted_sps_source','audit_lucid_sps_reconciliation_change','promote_sps_staged_order')), 'Role, parent, immutability, audit, and promotion functions exist.'
  union all select 'function_security','helpers are non-public with safe path', (select count(*)=4 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('assert_lucid_sps_write_role','validate_lucid_sps_parent_scope','protect_lucid_promoted_sps_source','audit_lucid_sps_reconciliation_change') and coalesce(array_to_string(p.proconfig,','),'') like '%search_path=public%' and not exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as acl where acl.grantee = 0 and acl.privilege_type = 'EXECUTE') and not has_function_privilege('anon',p.oid,'execute')), 'Trigger helpers cannot be directly invoked by browser roles.'
  union all select 'function_security','promotion is invoker/authenticated only', exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.oid='public.promote_sps_staged_order(uuid)'::regprocedure and not p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') like '%search_path=public%' and not exists (select 1 from aclexplode(coalesce(p.proacl, acldefault('f'::"char", p.proowner))) as acl where acl.grantee = 0 and acl.privilege_type = 'EXECUTE') and not has_function_privilege('anon',p.oid,'execute') and has_function_privilege('authenticated',p.oid,'execute')), 'Promotion relies on authenticated role and organization checks.'
  union all select 'rls','six SPS tables have RLS', (select count(*)=6 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('integration_customer_mappings','integration_ship_to_mappings','integration_item_mappings','sps_staged_orders','sps_staged_order_lines','sps_order_exceptions') and c.relrowsecurity), 'All SPS mapping/staging surfaces remain organization-scoped.'
  union all select 'promotion','860 denial', position('Purchase Order Change requires review and cannot be promoted as a new order.' in pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure)) > 0, '860 cannot become a new operational order.'
  union all select 'promotion','positive quantity and exact UOM checks', pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%l.quantity <= 0%' and pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%l.uom_status <> ''match''%', 'Promotion rejects invalid quantity and non-exact UOM.'
  union all select 'promotion','active target checks', pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%c.status <> ''active''%' and pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%i.status <> ''active''%', 'Promotion rejects inactive native targets.'
  union all select 'promotion','blocking exception and idempotency checks', pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%severity in (''warning'', ''blocking'')%' and pg_get_functiondef('public.promote_sps_staged_order(uuid)'::regprocedure) like '%if found then return query select existing_order_id, true%', 'Promotion blocks unresolved checks and returns existing order without remapping.'
)
select check_type, count(*) as expected_checks, count(*) filter(where passed) as passed_checks, count(*) filter(where not passed) as failed_checks, coalesce(string_agg(object_name, ', ' order by object_name) filter(where not passed), '') as missing_objects from checks group by check_type
union all
select 'FINAL RELEASE DECISION', count(*), count(*) filter(where passed), count(*) filter(where not passed), case when bool_and(passed) then 'POST-APPLY VERIFICATION PASS' else 'POST-APPLY VERIFICATION FAIL' end from checks
order by check_type;
